    for (uint64_t i = 0; i < new_cap; i++) {
        new_indices[i] = Z_T557_INDEX_EMPTY;
    }
    z_t557_entry_t* new_entries = (z_t557_entry_t*)z_xcalloc(new_cap, sizeof(z_t557_entry_t));
    uint64_t new_entries_len = 0;
